transformations.content:
proc format;
  value $gender
      'M','MALE' = 'Male'
      'F','FEMALE' = 'Female'
      other = 'Unknown';
  value ageband
      low -< 18 = 'Under 18'
      18  -< 30 = '18-29'
      30  -< 45 = '30-44'
      45  - high = '45+';
  invalue yorn
      'Y','YES','1' = 1
      'N','NO','0'  = 0
      other         = .;
run;

data &ds;
  call streaminit(&seed);

  length "Full Name"n $40 city $20 gender $6 note $200;
  format dob date9. created_dttm datetime19. salary dollar12.2;
  informat dob yymmdd10.;

  retain created_dttm "&g_run_dt"dt;

  do id = 1 to &n;
    "Full Name"n = catt('Person-', put(id, z4.));
    city = scan("Hyderabad Bengaluru Mumbai Delhi Chennai Pune", ceil(rand('uniform')*6), ' ');
    gender = ifc(rand('uniform')<0.5, 'M', 'F');
    dob = '01JAN1970'd + floor(rand('uniform')*20000);

    /* array + loops */
    array scores[5] _temporary_;
    do i = 1 to dim(scores);
      scores[i] = round(rand('normal', 70, 10), .01);
    end;

    /* SELECT/WHEN */
    select;
      when (scores[1] >= 85) note = 'Top performer';
      when (scores[1] >= 70) note = 'Average';
      otherwise note = 'Needs improvement';
    end;

    /* computed fields */
    salary = round(25000 + rand('uniform')*75000, .01);
    active = input(ifc(rand('uniform')<0.8,'Y','N'), yorn.);

    output;
  end;

  drop i;
run;

data &vw / view=&vw;
  set &base;
  where active = 1;
  label "Full Name"n = 'Employee Name';
run;

data work.lookup;
  infile datalines dlm=',' dsd truncover;
  length city $20 region $10;
  input city :$20. region :$10.;
datalines;
Hyderabad,South
Bengaluru,South
Mumbai,West
Delhi,North
Chennai,South
Pune,West
;
run;

proc sort data=work.sample out=work.sample_s;
  by city id;
run;

proc sort data=work.lookup out=work.lookup_s;
  by city;
run;

data work.enriched;
  merge work.sample_s(in=a) work.lookup_s(in=b);
  by city;

  if a;

  /* FIRST./LAST. logic */
  if first.city then city_count = 0;
  city_count + 1;
  if last.city then output;

  keep id "Full Name"n city region gender dob salary active city_count created_dttm note;
run;

data work.enriched_hash;
  if _n_ = 1 then do;
    declare hash h(dataset:"work.lookup_s");
    h.defineKey("city");
    h.defineData("region");
    h.defineDone();
    call missing(region);
  end;

  set work.sample_s;
  rc = h.find();
  if rc ne 0 then region = 'Unknown';

  drop rc;
run;

proc fcmp outlib=work.funcs.util;
  function clamp(x, lo, hi);
    if x < lo then return(lo);
    else if x > hi then return(hi);
    else return(x);
  endsub;

  function safe_ratio(num, den);
    if den = 0 then return(.);
    else return(num / den);
  endsub;
run;

data work.sample_fcmp;
  set work.sample;
  salary_clamped = clamp(salary, 30000, 90000);
  ratio = safe_ratio(salary_clamped, 100000);
run;

proc means data=work.sorted n mean min max;
  class city;
  var salary ratio;
  output out=work.means_out(drop=_type_ _freq_) n= mean= min= max= / autoname;
run;

proc freq data=work.sample;
  tables city*gender / chisq norow nocol nopercent;
  format gender $gender.;
run;

proc transpose data=work.means_out out=work.means_long name=stat;
  by city;
run;

ods listing close;
ods html5 path="&_root" file="report.html" (title="SAS Grammar Stress Report") style=htmlblue;

title "Salary Summary by City (&g_run_dt)";
proc report data=work.sql_summary nowd;
  columns city gender_label n n_active avg_salary pay_band;
  define city / group;
  define gender_label / group 'Gender';
  define n / analysis 'Count';
  define n_active / analysis 'Active';
  define avg_salary / analysis 'Avg Salary';
  define pay_band / display 'Band';
run;

proc datasets lib=work nolist;
  modify sample;
    label salary='Annual Salary (INR)';
    format dob date9. salary dollar12.2;
  quit;

data _null_;
  file logtxt lrecl=32767;
  put "Run datetime: &g_run_dt";
  put "Root path: &_root";
  put "Dataset rowcount (sample): " nobs=;
  if 0 then set work.sample nobs=nobs;
run;

data work.delta;
  set work.sample(obs=10);
  salary = salary * 1.05;
  note = catt(note, ' (adjusted)');
run;

data work.delta;
  set work.sample(obs=10);
  salary = salary * 1.05;
  note = catt(note, ' (adjusted)');
run;

proc sort data=work.sample out=work.sample_upd;
  by id;
run;

proc sort data=work.delta out=work.delta_upd;
  by id;
run;

data work.sample_updated;
  update work.sample_upd work.delta_upd;
  by id;
run;

data work.high_pay work.mid_pay work.low_pay;
  set work.sample_updated;
  length band $3;
  if salary >= 80000 then do; band='H'; output work.high_pay; end;
  else if salary >= 50000 then do; band='M'; output work.mid_pay; end;
  else do; band='L'; output work.low_pay; end;
run;

proc tabulate data=work.sample_updated;
  class city gender;
  var salary;
  table city,
        gender*(salary*(n mean min max))*f=comma10.;
  format gender $gender.;
run;

ods output Moments=work.moments BasicMeasures=work.basic;
proc univariate data=work.sample_updated;
  var salary;
  histogram salary / normal;
run;

ods graphics on;
proc sgplot data=work.sample_updated;
  vbox salary / category=city;
run;

proc sql noprint;
    select distinct city into :_cities separated by '|'
    from &ds
    order by city;
  quit;

proc sql;
      create table work.city_&i as
      select * from &ds
      where city = "&city";
    quit;

proc ds2;
  data work.ds2_out(overwrite=yes);
    dcl double x;
    method run();
      set work.sample_updated;
      x = salary / 1000;
      output;
    end;
  enddata;
run;

data work.ds2_out(overwrite=yes);
  dcl double x;
  method run();
    set work.sample_updated;
    x = salary / 1000;
    output;
  end;
enddata;
run;

proc import datafile=rawcsv out=work.imported dbms=csv replace;
  guessingrows=max;
run;

data _null_;
  file rawcsv;
  put "id,city,gender,salary";
  do id = 1 to 5;
    city = scan("Hyderabad Bengaluru Mumbai Delhi Chennai", id, ' ');
    gender = ifc(mod(id,2)=0,'F','M');
    salary = 45000 + id*5000;
    put id ',' city ',' gender ',' salary;
  end;
run;

data work.from_csv;
  infile rawcsv dsd firstobs=2 truncover;
  length city $20 gender $1;
  input id city :$20. gender :$1. salary;
run;

proc sql;
  create view work.v_high_salary as
  select *
  from work.sample_updated
  where salary >= (select median(salary) from work.sample_updated)
  ;
quit;

proc datasets lib=work nolist;
  copy in=work out=out memtype=data;
    select sql_summary means_out moments basic from_csv;
  quit;

