%macro make_data(ds=work.sample, n=100, seed=&g_seed);
  %local i;
  data &ds;
    call streaminit(&seed);

    length "Full Name"n $40 city $20 gender $6 note $200;
    format dob date9. created_dttm datetime19. salary dollar12.2;
    informat dob yymmdd10.;

    retain created_dttm "&g_run_dt"dt;

    do id = 1 to &n;
      "Full Name"n = catt('Person-', put(id, z4.));
      city = scan("Hyderabad Bengaluru Mumbai Delhi Chennai Pune", ceil(rand('uniform')*6), ' ');
      gender = ifc(rand('uniform')<0.5, 'M', 'F');
      dob = '01JAN1970'd + floor(rand('uniform')*20000);

      /* array + loops */
      array scores[5] _temporary_;
      do i = 1 to dim(scores);
        scores[i] = round(rand('normal', 70, 10), .01);
      end;

      /* SELECT/WHEN */
      select;
        when (scores[1] >= 85) note = 'Top performer';
        when (scores[1] >= 70) note = 'Average';
        otherwise note = 'Needs improvement';
      end;

      /* computed fields */
      salary = round(25000 + rand('uniform')*75000, .01);
      active = input(ifc(rand('uniform')<0.8,'Y','N'), yorn.);

      output;
    end;

    drop i;
  run;
%mend;

data &vw / view=&vw;
  set &base;
  where active = 1;
  label "Full Name"n = 'Employee Name';
run;

%macro macro_quoting_demo();
  %let raw = %str(A&B % (C) ; ' " );
  %let nr  = %nrstr(A&B % (C) ; ' " );
  %let bq  = %bquote(Hello, &raw);
  %put NOTE: raw=&raw;
  %put NOTE: nr=&nr;
  %put NOTE: bq=&bq;
%mend;

%macro city_loop(ds=work.sample_updated);
  %local dsc rc nobs i city;
  proc sql noprint;
    select distinct city into :_cities separated by '|'
    from &ds
    order by city;
  quit;

  %let i = 1;
  %do %while(%scan(&&_cities,&i,|) ne );
    %let city = %scan(&&_cities,&i,|);
    %put NOTE: Processing city=&city;

    proc sql;
      create table work.city_&i as
      select * from &ds
      where city = "&city";
    quit;

    %let i = %eval(&i + 1);
  %end;
%mend;
